1	import {createChatOrchestrator} from './chatOrchestrator.js';
2	import type {OrchestratorHooks} from './chatOrchestrator.js';
3	import type {AIProvider, MessageChunk, SendMessageParams, UsageMetadata} from '../types/ai.js';
4	import {AIError} from '../types/ai.js';
5	import type {ChatSession} from '../types/session.js';
6	import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
7	import {ToolRegistry} from './tools/registry.js';
8	import type {ToolResponse} from './tools/registry.js';
9	import type {OutgoingMessage} from '../types/messages.js';
10	import type {SessionEntry} from '../types/session.js';
11	
12	// Fixed: nothing asserts on it, and new Date() would tie the run to the clock.
13	const SENT_AT = '2026-01-01T00:00:00.000Z';
14	
15	// One expect per test needs the rejection as a value rather than a matcher.
16	const outcomeOf = (call: Promise<unknown>): Promise<string> =>
17	  call.then(() => 'resolved without throwing').catch((error: Error) => error.message);
18	
19	function createSession(content: string): ChatSession {
20	  return {
21	    sessionId: 's1',
22	    userId: 'u1',
23	    entries: [{role: 'user', content, timestamp: SENT_AT}],
24	  };
25	}
26	
27	function createMockProvider(response: string, usage?: UsageMetadata): AIProvider {
28	  return {
29	    async *sendMessage(_params: SendMessageParams): AsyncGenerator<MessageChunk> {
30	      yield {type: 'text', text: response};
31	      yield {type: 'stop', stopReason: 'end_turn', usage};
32	    },
33	    async generateStructured<T>(): Promise<T> {
34	      return {} as T;
35	    },
36	  };
37	}
38	
39	function createErrorProvider(error: Error): AIProvider {
40	  return {
41	    // eslint-disable-next-line require-yield
42	    async *sendMessage(): AsyncGenerator<MessageChunk> {
43	      throw error;
44	    },
45	    async generateStructured<T>(): Promise<T> {
46	      return {} as T;
47	    },
48	  };
49	}
50	
51	const promptBuilder = new PromptBuilder({identity: 'You are a test assistant.'});
52	
53	type RecordedHook =
54	  | 'beforeSession'
55	  | 'beforeUserInput'
56	  | 'afterUserInput'
57	  | 'beforeModelResponse'
58	  | 'afterModelResponse'
59	  | 'afterSession'
60	  | 'onError';
61	
62	// Only the named hooks are installed: one that merely exists changes the observed order.
63	const recordingHooks = (callOrder: string[], names: RecordedHook[]): OrchestratorHooks => {
64	  const all: Required<Pick<OrchestratorHooks, RecordedHook>> = {
65	    beforeSession: async () => void callOrder.push('beforeSession'),
66	    beforeUserInput: async (_session, msg) => {
67	      callOrder.push('beforeUserInput');
68	      return msg;
69	    },
70	    afterUserInput: async () => void callOrder.push('afterUserInput'),
71	    beforeModelResponse: async (_session, systemPrompt) => {
72	      callOrder.push('beforeModelResponse');
73	      return systemPrompt;
74	    },
75	    afterModelResponse: async () => void callOrder.push('afterModelResponse'),
76	    afterSession: async () => void callOrder.push('afterSession'),
77	    onError: async () => void callOrder.push('onError'),
78	  };
79	
80	  return Object.fromEntries(names.map(name => [name, all[name]])) as OrchestratorHooks;
81	};
82	
83	// Records what the orchestrator actually sent, for tests that assert on the request.
84	const capturingProvider = (): {provider: AIProvider; sent: {systemPrompt: string; lastUserContent: string}} => {
85	  const sent = {systemPrompt: '', lastUserContent: ''};
86	
87	  return {
88	    sent,
89	    provider: {
90	      async *sendMessage(params: SendMessageParams): AsyncGenerator<MessageChunk> {
91	        sent.systemPrompt = params.systemPrompt;
92	        const last = params.messages[params.messages.length - 1];
93	        sent.lastUserContent = typeof last.content === 'string' ? last.content : '';
94	        yield {type: 'text', text: 'ok'};
95	        yield {type: 'stop', stopReason: 'end_turn'};
96	      },
97	      async generateStructured<T>(): Promise<T> {
98	        return {} as T;
99	      },
100	    },
101	  };
102	};
103	
104	describe('ChatOrchestrator hooks', () => {
105	  describe('beforeSession', () => {
106	    it('called before anything else', async () => {
107	      const callOrder: string[] = [];
108	      const hooks = recordingHooks(callOrder, ['beforeSession', 'beforeUserInput', 'beforeModelResponse']);
109	
110	      const orchestrator = createChatOrchestrator(createMockProvider('hi'), promptBuilder, undefined, {hooks});
111	      await orchestrator.processMessage(createSession('hello'));
112	
113	      expect(callOrder[0]).toBe('beforeSession');
114	    });
115	
116	    it('failure reaches onError with the original error', async () => {
117	      const failure = new Error('before session failed');
118	      let captured: Error | undefined;
119	      const hooks: OrchestratorHooks = {
120	        beforeSession: async () => {
121	          throw failure;
122	        },
123	        onError: async (_session, error) => {
124	          captured = error;
125	        },
126	      };
127	
128	      const orchestrator = createChatOrchestrator(createMockProvider('ok'), promptBuilder, undefined, {hooks});
129	      const outcome = await outcomeOf(orchestrator.processMessage(createSession('hello')));
130	
131	      expect(outcome).toBe('before session failed');
132	      expect(captured).toBe(failure);
133	    });
134	  });
135	
136	  describe('afterSession', () => {
137	    it('called after everything completes', async () => {
138	      const callOrder: string[] = [];
139	      const hooks = recordingHooks(callOrder, ['afterModelResponse', 'afterSession']);
140	
141	      const orchestrator = createChatOrchestrator(createMockProvider('hi'), promptBuilder, undefined, {hooks});
142	      await orchestrator.processMessage(createSession('hello'));
143	
144	      expect(callOrder).toEqual(['afterModelResponse', 'afterSession']);
145	    });
146	
147	    it('called even when an error occurs', async () => {
148	      let afterSessionCalled = false;
149	      const hooks: OrchestratorHooks = {
150	        onError: async () => {},
151	        afterSession: async () => {
152	          afterSessionCalled = true;
153	        },
154	      };
155	
156	      const orchestrator = createChatOrchestrator(createErrorProvider(new Error('boom')), promptBuilder, undefined, {
157	        hooks,
158	      });
159	      const outcome = await outcomeOf(orchestrator.processMessage(createSession('hello')));
160	
161	      expect({outcome, afterSessionCalled}).toEqual({outcome: 'boom', afterSessionCalled: true});
162	    });
163	  });
164	
165	  describe('beforeUserInput', () => {
166	    it('receives the last user message content', async () => {
167	      let receivedMessage = '';
168	      const hooks: OrchestratorHooks = {
169	        beforeUserInput: async (_session, userMessage) => {
170	          receivedMessage = userMessage;
171	          return userMessage;
172	        },
173	      };
174	
175	      const orchestrator = createChatOrchestrator(createMockProvider('ok'), promptBuilder, undefined, {hooks});
176	      await orchestrator.processMessage(createSession('my answer'));
177	
178	      expect(receivedMessage).toBe('my answer');
179	    });
180	
181	    it('modifies user message when returning different value', async () => {
182	      const {provider, sent} = capturingProvider();
183	
184	      const hooks: OrchestratorHooks = {
185	        beforeUserInput: async (_session, _msg) => 'sanitized input',
186	      };
187	
188	      const orchestrator = createChatOrchestrator(provider, promptBuilder, undefined, {hooks});
189	      await orchestrator.processMessage(createSession('raw input'));
190	
191	      expect(sent.lastUserContent).toBe('sanitized input');
192	    });
193	  });
194	
195	  describe('afterUserInput', () => {
196	    it('receives user message after any beforeUserInput modification', async () => {
197	      let afterReceived = '';
198	      const hooks: OrchestratorHooks = {
199	        beforeUserInput: async (_s, _msg) => 'modified',
200	        afterUserInput: async (_s, msg) => {
201	          afterReceived = msg;
202	        },
203	      };
204	
205	      const orchestrator = createChatOrchestrator(createMockProvider('ok'), promptBuilder, undefined, {hooks});
206	      await orchestrator.processMessage(createSession('original'));
207	
208	      expect(afterReceived).toBe('modified');
209	    });
210	  });
211	
212	  describe('beforeModelResponse', () => {
213	    it('replaces system prompt with returned value', async () => {
214	      const {provider, sent} = capturingProvider();
215	
216	      const hooks: OrchestratorHooks = {
217	        beforeModelResponse: async (_session, _basePrompt) => 'Custom prompt for this question',
218	      };
219	
220	      const orchestrator = createChatOrchestrator(provider, promptBuilder, undefined, {hooks});
221	      await orchestrator.processMessage(createSession('hello'));
222	
223	      expect(sent.systemPrompt).toBe('Custom prompt for this question');
224	    });
225	  });
226	
227	  describe('afterModelResponse', () => {
228	    it('receives collected response text and usage', async () => {
229	      const usage: UsageMetadata = {inputTokens: 10, outputTokens: 5, totalTokens: 15};
230	      let receivedText = '';
231	      let receivedUsage: UsageMetadata | undefined;
232	
233	      const hooks: OrchestratorHooks = {
234	        afterModelResponse: async (_session, text, u) => {
235	          receivedText = text;
236	          receivedUsage = u;
237	        },
238	      };
239	
240	      const orchestrator = createChatOrchestrator(createMockProvider('hello world', usage), promptBuilder, undefined, {
241	        hooks,
242	      });
243	      await orchestrator.processMessage(createSession('hi'));
244	
245	      expect({receivedText, receivedUsage}).toEqual({receivedText: 'hello world', receivedUsage: usage});
246	    });
247	
248	    it('not called when stream throws', async () => {
249	      let afterCalled = false;
250	      const hooks: OrchestratorHooks = {
251	        afterModelResponse: async () => {
252	          afterCalled = true;
253	        },
254	        onError: async () => {},
255	      };
256	
257	      const orchestrator = createChatOrchestrator(
258	        createErrorProvider(new AIError('fail', 'TEST')),
259	        promptBuilder,
260	        undefined,
261	        {hooks}
262	      );
263	      const outcome = await outcomeOf(orchestrator.processMessage(createSession('hello')));
264	
265	      expect({outcome, afterCalled}).toEqual({outcome: 'fail', afterCalled: false});
266	    });
267	  });
268	
269	  describe('onError', () => {
270	    it('called with session and error when stream fails', async () => {
271	      let receivedError: Error | undefined;
272	      const hooks: OrchestratorHooks = {
273	        onError: async (_session, error) => {
274	          receivedError = error;
275	        },
276	      };
277	
278	      const orchestrator = createChatOrchestrator(
279	        createErrorProvider(new AIError('rate limited', 'RATE_LIMITED')),
280	        promptBuilder,
281	        undefined,
282	        {hooks}
283	      );
284	      const outcome = await outcomeOf(orchestrator.processMessage(createSession('hello')));
285	
286	      expect({outcome, receivedErrorMessage: receivedError?.message}).toEqual({
287	        outcome: 'rate limited',
288	        receivedErrorMessage: 'rate limited',
289	      });
290	    });
291	
292	    it('error still propagates after onError hook', async () => {
293	      const hooks: OrchestratorHooks = {
294	        onError: async () => {},
295	      };
296	
297	      const orchestrator = createChatOrchestrator(createErrorProvider(new Error('boom')), promptBuilder, undefined, {
298	        hooks,
299	      });
300	      await expect(orchestrator.processMessage(createSession('hello'))).rejects.toThrow('boom');
301	    });
302	  });
303	
304	  describe('full lifecycle order', () => {
305	    it('calls all hooks in correct order', async () => {
306	      const callOrder: string[] = [];
307	      const usage: UsageMetadata = {inputTokens: 5, outputTokens: 3, totalTokens: 8};
308	
309	      const hooks: OrchestratorHooks = {
310	        beforeSession: async () => {
311	          callOrder.push('beforeSession');
312	        },
313	        beforeUserInput: async (_s, msg) => {
314	          callOrder.push('beforeUserInput');
315	          return msg;
316	        },
317	        afterUserInput: async () => {
318	          callOrder.push('afterUserInput');
319	        },
320	        beforeModelResponse: async (_s, p) => {
321	          callOrder.push('beforeModelResponse');
322	          return p;
323	        },
324	        afterModelResponse: async () => {
325	          callOrder.push('afterModelResponse');
326	        },
327	        afterSession: async () => {
328	          callOrder.push('afterSession');
329	        },
330	      };
331	
332	      const orchestrator = createChatOrchestrator(createMockProvider('ok', usage), promptBuilder, undefined, {hooks});
333	      await orchestrator.processMessage(createSession('hello'));
334	
335	      expect(callOrder).toEqual([
336	        'beforeSession',
337	        'beforeUserInput',
338	        'afterUserInput',
339	        'beforeModelResponse',
340	        'afterModelResponse',
341	        'afterSession',
342	      ]);
343	    });
344	
345	    it('error path calls onError then afterSession', async () => {
346	      const callOrder: string[] = [];
347	
348	      const hooks = recordingHooks(callOrder, [
349	        'beforeSession',
350	        'beforeUserInput',
351	        'afterUserInput',
352	        'beforeModelResponse',
353	        'afterModelResponse',
354	        'onError',
355	        'afterSession',
356	      ]);
357	
358	      const orchestrator = createChatOrchestrator(createErrorProvider(new Error('fail')), promptBuilder, undefined, {
359	        hooks,
360	      });
361	      const outcome = await outcomeOf(orchestrator.processMessage(createSession('hello')));
362	
363	      expect({outcome, callOrder}).toEqual({
364	        outcome: 'fail',
365	        callOrder: [
366	          'beforeSession',
367	          'beforeUserInput',
368	          'afterUserInput',
369	          'beforeModelResponse',
370	          'onError',
371	          'afterSession',
372	        ],
373	      });
374	    });
375	  });
376	
377	  describe('no hooks', () => {
378	    it('works without any hooks configured', async () => {
379	      const orchestrator = createChatOrchestrator(createMockProvider('hello back'), promptBuilder);
380	      const result = await orchestrator.processMessage(createSession('hello'));
381	      expect(result).toBe('hello back');
382	    });
383	  });
384	});
385	
386	// One scripted round per sendMessage call, to drive the tool loop round by round.
387	const scriptedProvider = (rounds: MessageChunk[][]): AIProvider => {
388	  let round = 0;
389	
390	  return {
391	    async *sendMessage(): AsyncGenerator<MessageChunk> {
392	      for (const chunk of rounds[round++] ?? []) yield chunk;
393	    },
394	    async generateStructured<T>(): Promise<T> {
395	      return {} as T;
396	    },
397	  };
398	};
399	
400	const registryReturning = (response: ToolResponse): ToolRegistry => {
401	  const registry = new ToolRegistry();
402	  registry.register(
403	    {name: 'lookup', description: 'looks things up', inputSchema: {type: 'object'}},
404	    async () => response
405	  );
406	  return registry;
407	};
408	
409	const TOOL_CALL: MessageChunk = {type: 'tool_use', toolCall: {id: 'call-1', name: 'lookup', input: {q: 'x'}}};
410	const STOP_FOR_TOOL: MessageChunk = {type: 'stop', stopReason: 'tool_use'};
411	const STOP_DONE: MessageChunk = {type: 'stop', stopReason: 'end_turn'};
412	
413	const chunksFrom = async (stream: AsyncGenerator<MessageChunk>): Promise<MessageChunk[]> => {
414	  const chunks: MessageChunk[] = [];
415	  for await (const chunk of stream) chunks.push(chunk);
416	  return chunks;
417	};
418	
419	describe('ChatOrchestrator tool loop', () => {
420	  it('runs another round after a tool call and streams both rounds in order', async () => {
421	    const provider = scriptedProvider([
422	      [TOOL_CALL, STOP_FOR_TOOL],
423	      [{type: 'text', text: 'the answer'}, STOP_DONE],
424	    ]);
425	    const orchestrator = createChatOrchestrator(provider, promptBuilder, registryReturning({result: 'found it'}));
426	
427	    const chunks = await chunksFrom(orchestrator.processMessageStream(createSession('ask')));
428	
429	    expect(chunks.map(c => c.type)).toEqual(['tool_use', 'stop', 'text', 'stop']);
430	  });
431	
432	  it('stops after one round when nothing asked for a tool', async () => {
433	    const provider = scriptedProvider([[{type: 'text', text: 'done'}, STOP_DONE], [{type: 'text', text: 'never'}]]);
434	    const orchestrator = createChatOrchestrator(provider, promptBuilder, registryReturning({result: 'x'}));
435	
436	    const text = await orchestrator.processMessage(createSession('ask'));
437	
438	    expect(text).toBe('done');
439	  });
440	
441	  it('stops asking for tools once maxToolRounds is spent', async () => {
442	    const alwaysTools = Array.from({length: 10}, () => [TOOL_CALL, STOP_FOR_TOOL]);
443	    const orchestrator = createChatOrchestrator(
444	      scriptedProvider(alwaysTools),
445	      promptBuilder,
446	      registryReturning({result: 'again'}),
447	      {maxToolRounds: 2}
448	    );
449	
450	    const chunks = await chunksFrom(orchestrator.processMessageStream(createSession('ask')));
451	
452	    expect(chunks.filter(c => c.type === 'tool_use')).toHaveLength(3);
453	  });
454	
455	  it('forwards the client messages a tool returned as one tool_result chunk', async () => {
456	    const forwarded: OutgoingMessage = {type: 'entry_commit', index: 7};
457	    const orchestrator = createChatOrchestrator(
458	      scriptedProvider([[TOOL_CALL, STOP_FOR_TOOL], [STOP_DONE]]),
459	      promptBuilder,
460	      registryReturning({result: 'r', clientMessages: [forwarded]})
461	    );
462	
463	    const chunks = await chunksFrom(orchestrator.processMessageStream(createSession('ask')));
464	
465	    expect(chunks).toContainEqual({type: 'tool_result', clientMessages: [forwarded]});
466	  });
467	
468	  it('appends an upserted entry to the session and rewrites its index to match', async () => {
469	    const entry: SessionEntry = {role: 'assistant', content: 'from the tool', timestamp: SENT_AT, isStreaming: false};
470	    const orchestrator = createChatOrchestrator(
471	      scriptedProvider([[TOOL_CALL, STOP_FOR_TOOL], [STOP_DONE]]),
472	      promptBuilder,
473	      registryReturning({result: 'r', clientMessages: [{type: 'entry_upsert', index: 999, entry}]})
474	    );
475	    const session = createSession('ask');
476	
477	    const chunks = await chunksFrom(orchestrator.processMessageStream(session));
478	
479	    expect(chunks).toContainEqual({
480	      type: 'tool_result',
481	      clientMessages: [{type: 'entry_upsert', index: session.entries.length - 1, entry}],
482	    });
483	  });
484	
485	  it('asks for suppression when the tool says the reply is already handled', async () => {
486	    const orchestrator = createChatOrchestrator(
487	      scriptedProvider([[TOOL_CALL, STOP_FOR_TOOL], [STOP_DONE]]),
488	      promptBuilder,
489	      registryReturning({result: 'r', suppressAssistantResponse: true})
490	    );
491	
492	    const chunks = await chunksFrom(orchestrator.processMessageStream(createSession('ask')));
493	
494	    expect(chunks.map(c => c.type)).toEqual(['tool_use', 'stop', 'suppress_output', 'stop']);
495	  });
496	
497	  it('joins the text of every round, not only the last', async () => {
498	    let seen = '';
499	    const hooks: OrchestratorHooks = {
500	      afterModelResponse: async (_session, responseText) => {
501	        seen = responseText;
502	      },
503	    };
504	    const orchestrator = createChatOrchestrator(
505	      scriptedProvider([
506	        [{type: 'text', text: 'first '}, TOOL_CALL, STOP_FOR_TOOL],
507	        [{type: 'text', text: 'second'}, STOP_DONE],
508	      ]),
509	      promptBuilder,
510	      registryReturning({result: 'r'}),
511	      {hooks}
512	    );
513	
514	    await orchestrator.processMessage(createSession('ask'));
515	
516	    expect(seen).toBe('first second');
517	  });
518	
519	  it('keeps the usage an earlier round reported when a later round reports none', async () => {
520	    const usage: UsageMetadata = {inputTokens: 11, outputTokens: 3, totalTokens: 14};
521	    let seen: UsageMetadata | undefined;
522	    const hooks: OrchestratorHooks = {
523	      afterModelResponse: async (_session, _text, reported) => {
524	        seen = reported;
525	      },
526	    };
