describe('beforeSession failure acceptance', () => {
  it('rejects with the same error and runs onError and afterSession without starting the turn', async () => {
    const session: ChatSession = {
      sessionId: 's1',
      userId: 'u1',
      entries: [{role: 'user', content: 'hello', timestamp: '2026-01-01T00:00:00.000Z'}],
    };
    const failure = new Error('beforeSession failed');
    const events: string[] = [];
    const provider: AIProvider = {
      async *sendMessage(_params: SendMessageParams): AsyncGenerator<MessageChunk> {
        yield {type: 'stop', stopReason: 'end_turn'};
      },
      async generateStructured<T>(): Promise<T> {
        return {} as T;
      },
    };
    const orchestrator = createChatOrchestrator(provider, new PromptBuilder({identity: 'test'}), undefined, {
      hooks: {
        beforeSession: async () => {
          events.push('beforeSession');
          throw failure;
        },
        beforeUserInput: async (_session, message) => {
          events.push('beforeUserInput');
          return message;
        },
        onError: async (receivedSession, error) => {
          events.push('onError');
          expect(receivedSession).toBe(session);
          expect(error).toBe(failure);
        },
        afterSession: async receivedSession => {
          events.push('afterSession');
          expect(receivedSession).toBe(session);
        },
      },
    });

    let receivedError: unknown;
    try {
      await orchestrator.processMessage(session);
    } catch (error) {
      receivedError = error;
    }

